 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Nonzero horizontal runs (length >= 2) are the model patterns. Isolated
    # cells are markers to be expanded using the pattern containing their color.
    patterns = []
    for row in grid:
        c = 0
        while c < w:
            if row[c] == 0:
                c += 1
                continue
            a = c
            while c < w and row[c] != 0:
                c += 1
            if c - a >= 2:
                patterns.append((row[a:c], a, c))

    for r in range(h):
        c = 0
        while c < w:
            if grid[r][c] == 0:
                c += 1
                continue
            a = c
            while c < w and grid[r][c] != 0:
                c += 1
            if c - a != 1:
                continue
            v = grid[r][a]
            # Prefer a pattern whose color sequence contains the marker.
            choices = [p for p in patterns if v in p[0]]
            if not choices:
                continue
            # If multiple motifs contain this color, use the shortest one;
            # otherwise preserve the complete reference run.
            pat, _, _ = min(choices, key=lambda p: len(p[0]))
            k = pat.index(v)
            start = a - k
            for j, color in enumerate(pat):
                x = start + j
                if 0 <= x < w:
                    out[r][x] = color
    return out
